/* blitter module: case table layout (generated by tools/gen_blitter.py into
 * blitter_tab.c; the flags must match BF_* there). */
#ifndef AMT_BLITTER_H
#define AMT_BLITTER_H

#include <exec/types.h>

#define BF_LINE     0x0001   /* line mode: apt is the raw error term */
#define BF_BIG      0x0002   /* ECS: start through BLTSIZV/BLTSIZH */
#define BF_ECS      0x0004   /* needs ECS Agnus (skip on OCS) */
#define BF_NOZERO   0x0008   /* do not check BZERO */
#define BF_CON0L    0x0010   /* ECS: write BLTCON0L = aux after BLTCON0 */
#define BF_SPECIAL  0x0020   /* only run by a special test */
#define BF_HOT      0x0040   /* also run under amt_hot() */

/* words at pool+off: odd seed -> xorshift32 upper halves, even -> seed>>16 */
struct blt_fill {
    ULONG off;
    UWORD words;
    ULONG seed;
};

struct blt_case {
    const char *id;
    UWORD con0, con1, afwm, alwm;
    UWORD adat, bdat, cdat, aux;
    WORD  amod, bmod, cmod, dmod;
    ULONG apt, bpt, cpt, dpt;        /* pool offsets (apt: error term in line mode) */
    UWORD size, sizv, sizh, flags;
    UWORD fill0, nfill;
    ULONG win_off, win_len;          /* CRC window (destination + guards) */
    ULONG crc;                       /* expected CRC-32 of the window */
    UBYTE zero;                      /* expected BZERO: 0, 1, or 2 = not checked */
    UWORD w, h;                      /* words x rows (informational) */
};

extern const struct blt_fill blt_fills[];
extern const struct blt_case blt_cases[];
extern const int blt_ncases;

#endif
